mapper.select:
select id, user_id, role_id, added_by, added_at
from sys_user_role
where user_id = #{userId}

select id, user_id, role_id, added_by, added_at from sys_user_role where user_id in
#{userId}
order by user_id, role_id

select role_id, count(*) user_count from sys_user_role where role_id in
#{roleId}
group by role_id
